(async () => {
  let chat;
  try {
    chat = await import("/w/node_modules/agents/dist/chat/index.js");
  } catch (e) {
    console.error("ERROR: cannot load agents/chat: " + e.message);
    process.exit(2);
  }
  if (typeof chat.reconcileMessages !== "function") {
    console.error("ERROR: reconcileMessages is not exported");
    process.exit(2);
  }
  const server = [
    { id: "u1", role: "user", parts: [{ type: "text", text: "first" }] },
    { id: "a1", role: "assistant", parts: [{ type: "tool-search", toolCallId: "call_0", state: "output-available", input: { q: "cats" }, output: "cats result" }] },
    { id: "u2", role: "user", parts: [{ type: "text", text: "second" }] }
  ];
  const incoming = [
    server[0],
    server[1],
    server[2],
    { id: "a2", role: "assistant", parts: [{ type: "tool-search", toolCallId: "call_0", state: "input-available", input: { q: "dogs" } }] }
  ];
  const out = chat.reconcileMessages(incoming, server);
  const last = out[out.length - 1];
  const part = last && last.parts && last.parts[0];
  if (out.length !== 4 || !part || part.toolCallId !== "call_0") {
    console.error("ERROR: unexpected reconcileMessages result " + JSON.stringify(out));
    process.exit(2);
  }
  if (last.id === "a2" && part.state === "input-available" && !("output" in part)) {
    console.log("OK: the new turn's reused toolCallId call_0 stays pending; the earlier turn's output is not attached");
    process.exit(0);
  }
  if (part.state === "output-available" && part.output === "cats result") {
    console.error("FAIL: a later turn reusing toolCallId call_0 got the earlier turn's tool output");
    process.exit(1);
  }
  console.error("ERROR: unexpected last message " + JSON.stringify(last));
  process.exit(2);
})();

